# Third-party SDK. Do not edit this file.
class LegacyPayClient:
    def __init__(self, key):
        self.key = key
        self.calls = []

    def doTransaction(self, amount_in_cents, currency_code, card_token):
        self.calls.append((amount_in_cents, currency_code, card_token))
        return {"status_code": "00", "ref": "LP-%d" % len(self.calls)}
